# -*- coding: utf-8 -*-
import html
def e(s): return html.escape(s, quote=True)
def T(label, hint, tips, ks=(0, 1)):
    return (label, hint, tips if isinstance(tips, dict) else {k: tips for k in ks})
def I(label, hint, ans, fb):
    return (label, hint, ans, fb)

KEY = 'wesser-serie-primeros100'

FASES = [('Fase 1', 'Días 1 a 12'), ('Fase 2', 'Días 13 a 45'), ('Fase 3', 'Días 46 a 90')]
def fb(n):
    o = ['<div class="fb" role="group" aria-label="%s">' % ('Estás en la fase %d de 3' % n if n else 'Las tres fases de los 100 días')]
    for i, (a, b) in enumerate(FASES, 1):
        on = (i == n)
        o.append('<span%s%s><b>%s</b><small>%s</small></span>' % (' class="on"' if on else '', ' aria-current="step"' if on else '', a, b))
    o.append('</div>')
    return ''.join(o)

def lista(titulo, filas, clase='faq'):
    o = ['<section><h2 class="lab">%s</h2><div class="%s">' % (e(titulo), clase)]
    for b, t in filas:
        o.append('<div><b>%s</b><p>%s</p></div>' % (e(b), e(t)))
    o.append('</div></section>')
    return ''.join(o)

def frases(titulo, fr):
    return '<section><h2 class="lab">%s</h2><ul class="ls">%s</ul></section>' % (e(titulo), ''.join('<li>%s</li>' % e(x) for x in fr))

